language "moriarty-sherlock-draft/1";
program P {
  fn id(xs: List): List { xs }
  entry id(cons(1, cons(2, nil)));
}

language "moriarty-sherlock-nominal/1";
program P {
  type Schedule { Done; Pay(a_amount: UInt, b_next: UInt); }
  fn pick(s: Schedule): UInt { match s { Schedule::Pay(x, x) => x, Schedule::Done() => 0 } }
  entry pick(construct Schedule::Done());
}

language "moriarty-sherlock-nominal/1";
program P {
  type Schedule { Done; Pay(a_amount: UInt, b_next: UInt); }
  fn pick(s: Schedule): UInt { match s { Schedule::Pay(x, y) => x, Schedule::Done() => 0 } }
  fn other(s: Schedule): UInt { match s { Schedule::Pay(x, y) => y, Schedule::Done() => 1 } }
  entry pick(construct Schedule::Done());
}
